return items.map(item => {

  // ETAPA 2: LIMPIEZA Y TRANSFORMACIÓN (ACTUALIZADO)


  //  1. Normalizar RUT (elimina puntos y espacios)

  let rut = String(item.json.rut_cliente || '').replace(/[.\s]/g, '').toUpperCase().trim();

  // 2. Normalizar fecha (DD/MM/YYYY → YYYY-MM-DD)

  let fecha = String(item.json.fecha_solicitud || '').trim();
  const matchFecha = fecha.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (matchFecha) {
    fecha = `${matchFecha[3]}-${matchFecha[2].padStart(2,'0')}-${matchFecha[1].padStart(2,'0')}`;
  }

  // 3. Convertir valores numéricos de forma segura 

  let monto = parseFloat(item.json.monto_solicitado);
  let edad  = parseInt(item.json.edad);

  // Captura el ingreso mensual aunque n8n lo detecte como Texto (String)

  let ingresoRaw = item.json.ingreso_mensual;
  let ingreso = 0;

  if (ingresoRaw !== undefined && ingresoRaw !== null && ingresoRaw !== '') {
    // Si viene con formato de texto, elimina puntos fantasmas y convierte a número real
    ingreso = parseFloat(String(ingresoRaw).replace(/[.\s]/g, ''));
  } else {
    ingreso = 0; // Si la celda venía vacía en el Excel, le asigna 0 para evitar el NULL
  }

  // 4. Normalizar email y nombre

  let email  = String(item.json.email || '').trim().toLowerCase();
  let nombre = String(item.json.nombre_cliente || '').trim();

  // ETAPA 3: VALIDACIÓN (6 reglas de negocio bancarias)
  // 
  const regexFecha = /^\d{4}-\d{2}-\d{2}$/;
  const regexEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const fechaValida   = regexFecha.test(fecha);
  const emailValido   = regexEmail.test(email);
  const montoValido   = !isNaN(monto)  && monto > 0 && monto <= 50000000;
  const ingresoValido = !isNaN(ingreso) && ingreso > 0;
  const edadValida    = !isNaN(edad)   && edad >= 18 && edad <= 75;
  const rutValido     = rut.length > 0;

  // Si alguna validación falla → rechazado
  if (!fechaValida || !emailValido || !montoValido || !ingresoValido || !edadValida || !rutValido) {
    item.json.rut_cliente        = rut;
    item.json.nombre_cliente     = nombre;
    item.json.email              = email;
    item.json.fecha_solicitud    = fecha;
    item.json.estado_calidad     = "rechazado";

    let errores = [];
    if (!fechaValida)   errores.push("Fecha inválida");
    if (!emailValido)   errores.push("Email inválido");
    if (!montoValido)   errores.push("Monto inválido (debe ser >0 y ≤50.000.000)");
    if (!ingresoValido) errores.push("Ingreso no positivo");
    if (!edadValida)    errores.push(`Edad fuera de rango legal [18-75]: ${edad}`);
    if (!rutValido)     errores.push("RUT vacío");

    item.json.observacion = errores.join(" | ");
    return item;
  }

  // ETAPA 4 (prep): TRANSFORMACIÓN FINAL
  // Calcula cuota estimada = monto / 24 meses
  // 

  // Si alguna validación falla -> rechazado
    if (!fechaValida || !emailValido || !montoValido || !ingresoValido || !edadValida || !rutValido) {
        item.json.rut_cliente     = rut;
        item.json.nombre_cliente  = nombre;
        item.json.email           = email;
        item.json.fecha_solicitud = fecha;
        item.json.monto_solicitado = monto;
        item.json.estado_calidad   = "rechazado"; // <- IMPORTANTE
        item.json.observacion     = errores.join(" | ");
    } else {
        // ETAPA 4: Si todo está OK, calculamos valores finales y marcamos como válido
        item.json.rut_cliente      = rut;
        item.json.nombre_cliente   = nombre;
        item.json.email            = email;
        item.json.fecha_solicitud  = fecha;
        item.json.monto_solicitado = monto;
        item.json.ingreso_mensual  = ingreso;
        item.json.edad             = edad;
        item.json.total_cuota      = parseFloat((monto / 24).toFixed(0));
        item.json.estado_calidad   = "valido";    // <- IMPORTANTE
        item.json.observacion      = "";
    }

    return item;
});
